// Deterministic synthetic fixture generator.
//
// Emits the fixture corpus committed under fixtures/. The output is fully
// determined by the seed and the tables below, so the corpus can be
// regenerated byte-for-byte without real data ever entering the repository
// (DEC-18). Run: node scripts/generate-fixtures.mjs
//
// Decisions obeyed: DEC-18 (synthetic only), DEC-13 (risk tier per intent),
// DEC-22 (documents + canonical resolutions), DEC-23 (owner + review_by),
// DEC-31 (770 cases, 385 fit / 385 report), section 4.11 (<=25 intents,
// 'other' group kept).

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const FIXTURES = join(ROOT, 'fixtures');

const SEED = 0x41726361; // 'Arca'
const TOTAL_TICKETS = 770;
const HALF = TOTAL_TICKETS / 2;

// ---------------------------------------------------------------------------
// Taxonomy: 24 named intents + 'other' = 25 (the DEC-10 / section 4.11 cap).
// ---------------------------------------------------------------------------

const INTENTS = [
  // High risk tier (DEC-13): money and data-subject rights.
  { id: 'refund-request', label: 'Refund request', risk_tier: 'high', queue: 'billing', refund_rate: 0.7 },
  { id: 'billing-dispute', label: 'Billing dispute', risk_tier: 'high', queue: 'billing', refund_rate: 0.35 },
  { id: 'cancel-subscription', label: 'Cancel subscription', risk_tier: 'high', queue: 'billing', refund_rate: 0.2 },
  { id: 'data-deletion-request', label: 'Data deletion request', risk_tier: 'high', queue: 'accounts', refund_rate: 0 },
  { id: 'chargeback-notice', label: 'Chargeback notice', risk_tier: 'high', queue: 'billing', refund_rate: 0.55 },
  // Medium risk tier.
  { id: 'payment-failure', label: 'Payment failure', risk_tier: 'medium', queue: 'billing', refund_rate: 0 },
  { id: 'plan-change-question', label: 'Plan change question', risk_tier: 'medium', queue: 'billing', refund_rate: 0 },
  { id: 'invoice-copy-request', label: 'Invoice copy request', risk_tier: 'medium', queue: 'billing', refund_rate: 0, macro: 'MACRO-INVOICE-RESEND' },
  { id: 'account-recovery', label: 'Account recovery', risk_tier: 'medium', queue: 'accounts', refund_rate: 0 },
  { id: 'login-trouble', label: 'Login trouble', risk_tier: 'medium', queue: 'accounts', refund_rate: 0, macro: 'MACRO-PASSWORD-RESET' },
  { id: 'sync-error-report', label: 'Sync error report', risk_tier: 'medium', queue: 'technical', refund_rate: 0 },
  { id: 'export-broken', label: 'Export broken', risk_tier: 'medium', queue: 'technical', refund_rate: 0 },
  { id: 'integration-failure', label: 'Integration failure', risk_tier: 'medium', queue: 'technical', refund_rate: 0 },
  // Low risk tier.
  { id: 'feature-request', label: 'Feature request', risk_tier: 'low', queue: 'general', refund_rate: 0 },
  { id: 'how-to-question', label: 'How-to question', risk_tier: 'low', queue: 'general', refund_rate: 0, macro: 'MACRO-KB-LINK' },
  { id: 'pricing-question', label: 'Pricing question', risk_tier: 'low', queue: 'general', refund_rate: 0 },
  { id: 'documentation-gap', label: 'Documentation gap', risk_tier: 'low', queue: 'general', refund_rate: 0 },
  { id: 'feedback-positive', label: 'Positive feedback', risk_tier: 'low', queue: 'general', refund_rate: 0 },
  { id: 'bug-minor-report', label: 'Minor bug report', risk_tier: 'low', queue: 'technical', refund_rate: 0 },
  { id: 'onboarding-help', label: 'Onboarding help', risk_tier: 'low', queue: 'accounts', refund_rate: 0 },
  { id: 'notification-settings-help', label: 'Notification settings help', risk_tier: 'low', queue: 'accounts', refund_rate: 0 },
  { id: 'mobile-app-question', label: 'Mobile app question', risk_tier: 'low', queue: 'technical', refund_rate: 0 },
  { id: 'api-usage-question', label: 'API usage question', risk_tier: 'low', queue: 'technical', refund_rate: 0, macro: 'MACRO-API-DOCS-LINK' },
  { id: 'status-inquiry', label: 'Service status inquiry', risk_tier: 'low', queue: 'technical', refund_rate: 0 },
  // The 'other' group that section 4.11 requires. The induction job examines it.
  { id: 'other', label: 'Other', risk_tier: 'medium', queue: 'general', refund_rate: 0 },
];

if (INTENTS.length > 25) throw new Error(`taxonomy exceeds 25 intents: ${INTENTS.length}`);

const ESCALATION_RATE = { high: 0.5, medium: 0.2, low: 0.05 };

// One subject and one body per named intent. All text is invented. No names,
// addresses, phone numbers or account identifiers appear anywhere (DEC-18).
const TEXT = {
  'refund-request': ['Charged twice this month', 'I see two charges for one subscription month and I want the duplicate refunded.'],
  'billing-dispute': ['Invoice total does not match the plan', 'The invoice total is higher than the plan price shown on the pricing page.'],
  'cancel-subscription': ['Close the subscription at period end', 'Please close the workspace subscription when the current period ends.'],
  'data-deletion-request': ['Remove all stored data', 'I want every record tied to the workspace erased under the deletion policy.'],
  'chargeback-notice': ['Bank opened a dispute', 'The bank started a dispute for last month and the case needs your response.'],
  'payment-failure': ['Card declined without reason', 'Renewal failed with a decline message although the card works everywhere else.'],
  'plan-change-question': [ 'Switch to the annual plan', 'How do I move the workspace to annual billing before the next renewal date?'],
  'invoice-copy-request': ['Need a past invoice again', 'Send a fresh copy of the invoice from three periods ago for the finance archive.'],
  'account-recovery': ['Locked out after losing the second factor', 'The backup codes are gone and the sign-in page rejects every method.'],
  'login-trouble': ['Password reset mail never arrives', 'The reset message does not reach any folder and sign-in keeps failing.'],
  'sync-error-report': ['Desktop client stops syncing', 'The desktop client pauses sync every few minutes and shows error E-412.'],
  'export-broken': ['Export produces an empty archive', 'The full export finishes in seconds and the archive contains no records.'],
  'integration-failure': ['Calendar link drops daily', 'The calendar connection disconnects once a day and needs manual relinking.'],
  'feature-request': ['Request for saved filter views', 'Saved filter views would remove the same setup steps every morning.'],
  'how-to-question': ['Assign tasks to several people', 'Can one task carry more than one assignee in the current plans?'],
  'pricing-question': ['Seats above the plan limit', 'What happens to billing when the seat count passes the plan limit mid-period?'],
  'documentation-gap': ['Docs miss the bulk import steps', 'The import guide skips the field mapping screen that appears after upload.'],
  'feedback-positive': ['Reports page saves hours', 'The weekly summary gives the numbers that used to need a spreadsheet session.'],
  'bug-minor-report': ['Typo on the settings page', 'The settings header spells the word notifications wrong on every load.'],
  'onboarding-help': ['First workspace setup stuck', 'The setup checklist stays on step two although the sample project imported.'],
  'notification-settings-help': ['Digest arrives at night', 'The digest lands at midnight local time and the schedule control looks ignored.'],
  'mobile-app-question': ['Offline edits on mobile', 'Do edits made offline in the mobile app merge without conflicts afterwards?'],
  'api-usage-question': ['Pagination stops at one page', 'The list endpoint returns the first page and ignores the cursor parameter.'],
  'status-inquiry': ['Slow responses this morning', 'Responses lag since the morning window. Is there an incident on the status page?'],
  other: ['Question about the team plan trial', 'The trial banner disappeared early and the remaining days are unclear.'],
};

const BODY_SUFFIXES = [
  'This started today.',
  'This happens every time.',
  'No settings change helps so far.',
  'The steps repeat on a clean install.',
];

const REVIEWERS = ['support-docs-team', 'support-ops-team', 'platform-docs-team'];

// ---------------------------------------------------------------------------
// Seeded PRNG (mulberry32). Determinism is the whole point of this script.
// ---------------------------------------------------------------------------

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(SEED);
const pick = (list) => list[Math.floor(rng() * list.length)];
const between = (lo, hi) => lo + Math.floor(rng() * (hi - lo + 1));
const chance = (rate) => rng() < rate;

// ---------------------------------------------------------------------------
// Gold set: stratify by intent (this nests the three risk-tier strata from
// section 4.10). 770 = 25 x 30 + 20, so 20 intents get 31 tickets and 5 get
// 30. Odd counts alternate the spare ticket between the fit and report halves
// so both halves land on exactly 385.
// ---------------------------------------------------------------------------

const counts = INTENTS.map((_, i) => (i < TOTAL_TICKETS - INTENTS.length * 30 ? 31 : 30));
let fitSpare = true;
const splitsFor = (n) => {
  const fitHalf = Math.floor(n / 2) + (n % 2 === 1 && fitSpare ? 1 : 0);
  fitSpare = !fitSpare;
  return { fit: fitHalf, report: n - fitHalf };
};

let seq = 0;
const nextId = () => `SYN-${String(++seq).padStart(6, '0')}`;

function makeTicket(intent) {
  const escalated = chance(ESCALATION_RATE[intent.risk_tier]);
  const macro = intent.macro && chance(0.6) ? intent.macro : null;
  const queue = chance(0.85) ? intent.queue : 'general';
  const refundIssued = chance(intent.refund_rate);
  const minutes = escalated ? between(10, 90) : intent.risk_tier === 'high' ? between(20, 180) : between(45, 480);
  const [subject, body] = TEXT[intent.id];
  const suffix = chance(0.4) ? ` ${pick(BODY_SUFFIXES)}` : '';
  return {
    ticket_id: nextId(),
    source: 'synthetic',
    intent: intent.id,
    queue,
    disposition: {
      escalated,
      macro_applied: macro,
      refund_issued: refundIssued,
      first_reply_minutes: minutes,
    },
    subject,
    body: body + suffix,
  };
}

const fitTickets = [];
const reportTickets = [];
for (let i = 0; i < INTENTS.length; i++) {
  const { fit, report } = splitsFor(counts[i]);
  for (let k = 0; k < fit; k++) fitTickets.push(makeTicket(INTENTS[i]));
  for (let k = 0; k < report; k++) reportTickets.push(makeTicket(INTENTS[i]));
}

if (fitTickets.length !== HALF || reportTickets.length !== HALF) {
  throw new Error(`split broken: fit=${fitTickets.length} report=${reportTickets.length}`);
}

// ---------------------------------------------------------------------------
// Retrieval corpus: help-center documents plus canonical resolutions
// (DEC-22). Every entry declares an owner and a review date (DEC-23).
// ---------------------------------------------------------------------------

function doc(id, kind, title, body, path, ownerIdx, reviewBy, linkedIntents) {
  return {
    doc_id: id,
    kind, // 'document' | 'canonical_resolution'
    title,
    body,
    url: `https://help.example.com/${path}`,
    owner: REVIEWERS[ownerIdx],
    review_by: reviewBy,
    linked_intents: linkedIntents,
  };
}

const DOCUMENTS = [
  doc('DOC-SYN-001', 'document', 'Billing cycles and invoices explained',
    'This article explains renewal dates, proration and where the finance archive lists every past invoice copy.',
    'articles/billing-cycles', 0, '2026-03-01', ['invoice-copy-request', 'billing-dispute']),
  doc('DOC-SYN-002', 'document', 'Requesting a refund',
    'This article lists the refund windows per plan and the steps that the billing queue follows for each case.',
    'articles/refunds', 0, '2026-02-15', ['refund-request', 'chargeback-notice']),
  doc('DOC-SYN-003', 'document', 'Closing a subscription',
    'This article describes period-end closure, what happens to stored records and how reactivation works.',
    'articles/cancellation', 0, '2026-04-01', ['cancel-subscription']),
  doc('DOC-SYN-004', 'document', 'Data deletion requests',
    'This article walks through the deletion policy, the verification step and the erase window per region.',
    'articles/data-deletion', 1, '2026-01-31', ['data-deletion-request']),
  doc('DOC-SYN-005', 'document', 'Fixing sync errors in the desktop client',
    'This article covers pause states, error codes such as E-412 and the reconnect procedure for stalled clients.',
    'articles/sync-errors', 2, '2026-03-15', ['sync-error-report']),
  doc('DOC-SYN-006', 'document', 'Recovering access to an account',
    'This article explains the recovery flow when the second factor and the backup codes are both unavailable.',
    'articles/account-recovery', 1, '2026-02-28', ['account-recovery', 'login-trouble']),
  doc('DOC-SYN-007', 'document', 'Export formats and limits',
    'This article lists the export formats, the empty-archive causes and the retry rule for partial exports.',
    'articles/exports', 2, '2026-05-01', ['export-broken']),
  doc('DOC-SYN-008', 'document', 'List endpoints and cursor pagination',
    'This article shows the cursor parameter, the page size default and the header that reports the next cursor.',
    'articles/api-pagination', 2, '2026-04-15', ['api-usage-question', 'integration-failure']),
  // Canonical resolutions pair a resolved outcome with the intents they answer.
  doc('RES-SYN-101', 'canonical_resolution', 'Resolved: duplicate charge refunded',
    'Outcome: the billing queue verified the double charge, refunded the duplicate and confirmed the correct renewal date.',
    'resolutions/duplicate-charge', 0, '2026-03-01', ['refund-request', 'billing-dispute']),
  doc('RES-SYN-102', 'canonical_resolution', 'Resolved: password reset delivered',
    'Outcome: the accounts queue cleared the blocked send, issued a fresh reset message and confirmed sign-in.',
    'resolutions/reset-delivered', 1, '2026-02-15', ['login-trouble']),
  doc('RES-SYN-103', 'canonical_resolution', 'Resolved: subscription closed at period end',
    'Outcome: the billing queue scheduled closure for the period end and sent the confirmation with the final invoice.',
    'resolutions/period-end-close', 0, '2026-04-01', ['cancel-subscription']),
  doc('RES-SYN-104', 'canonical_resolution', 'Resolved: calendar relinked permanently',
    'Outcome: the technical queue rotated the stale token, updated the integration scope and stopped the daily drop.',
    'resolutions/calendar-relink', 2, '2026-03-15', ['integration-failure']),
  doc('RES-SYN-105', 'canonical_resolution', 'Resolved: digest schedule corrected',
    'Outcome: the accounts queue matched the timezone offset, rescheduled the digest and verified the delivery slot.',
    'resolutions/digest-schedule', 1, '2026-05-01', ['notification-settings-help']),
  doc('RES-SYN-106', 'canonical_resolution', 'Resolved: incident confirmed and tracked',
    'Outcome: the technical queue matched the slowdown to the active incident and attached the ticket to its tracker.',
    'resolutions/incident-link', 2, '2026-01-31', ['status-inquiry']),
];

// ---------------------------------------------------------------------------
// Write everything.
// ---------------------------------------------------------------------------

mkdirSync(join(FIXTURES, 'gold'), { recursive: true });
writeJson(join(FIXTURES, 'taxonomy.json'), {
  version: 1,
  intent_cap: 25,
  intents: INTENTS.map(({ id, label, risk_tier }) => ({ id, label, risk_tier })),
});
writeJson(join(FIXTURES, 'gold', 'fit.json'), {
  split: 'fit', source: 'synthetic', count: fitTickets.length, tickets: sortById(fitTickets),
});
writeJson(join(FIXTURES, 'gold', 'report.json'), {
  split: 'report', source: 'synthetic', count: reportTickets.length, tickets: sortById(reportTickets),
});
writeJson(join(FIXTURES, 'documents.json'), { version: 1, documents: DOCUMENTS });

console.log(
  `fixtures: taxonomy=${INTENTS.length} intents, gold fit=${fitTickets.length} ` +
  `report=${reportTickets.length}, documents=${DOCUMENTS.length}`,
);

function writeJson(path, value) {
  writeFileSync(path, JSON.stringify(value, null, 2) + '\n');
}
function sortById(tickets) {
  return [...tickets].sort((a, b) => a.ticket_id.localeCompare(b.ticket_id));
}
